#!/usr/bin/env python3
"""Run PR evaluations selected by the repository's manifest.

The step bundles this file with sync_commands.py because ci-operator distributes
the commands file, not sibling Python files. Only PyYAML and the stdlib are needed.
"""

import json
import os
from pathlib import Path, PurePosixPath
import shlex
import signal
import subprocess
import sys
import tarfile
import tempfile
import time
import uuid
import xml.etree.ElementTree as ET
from dataclasses import dataclass

import yaml

try:  # Package imports for repository tooling; direct imports for the CI bundle.
    from .eval_report import render_report
    from .eval_config import HARNESS_REVISION, HARNESS_URL, validate_resolution_result
    from .eval_plan import EvalError, EvalPlan, artifact_name, changed_files, relative_path, repo_directory, repo_file
    from .eval_plan import validate_thresholds
except ImportError:
    from eval_report import render_report
    from eval_config import HARNESS_REVISION, HARNESS_URL, validate_resolution_result
    from eval_plan import EvalError, EvalPlan, artifact_name, changed_files, relative_path, repo_directory, repo_file
    from eval_plan import validate_thresholds


MANIFEST = "evals.yaml"
STEP_TIMEOUT = 13800  # Leave ten minutes inside the Prow step's four-hour limit.
EVAL_TIMEOUT = 12600
CONFIG_RESOLUTION_TIMEOUT = 60



class Interrupted(BaseException):
    """Stop scheduling evals when Prow terminates the step."""


class UniqueKeyLoader(yaml.SafeLoader):  # pylint: disable=too-many-ancestors
    """Do not silently accept a duplicate manifest setting."""


def unique_mapping(loader, node, deep=False):
    result = {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node, deep=deep)
        if not isinstance(key, str) or key in result:
            raise EvalError("manifest keys must be unique strings")
        result[key] = loader.construct_object(value_node, deep=deep)
    return result


UniqueKeyLoader.add_constructor(
    yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, unique_mapping)


@dataclass(frozen=True)
class Eval:
    config: str
    run: str
    parallelism: int
    max_turns: int
    setup_script: str
    triggers: tuple
    eval_cases_dir: str = ""


def load_manifest(repo):
    try:
        with repo_file(repo, MANIFEST, "manifest").open(encoding="utf-8") as stream:
            document = yaml.load(stream, Loader=UniqueKeyLoader)
    except (OSError, yaml.YAMLError) as error:
        raise EvalError(f"cannot read {MANIFEST}: {error}") from error
    if not isinstance(document, dict) or set(document) != {"evals"}:
        raise EvalError("manifest must be a mapping containing only 'evals'")
    if not isinstance(document["evals"], list):
        raise EvalError("evals must be a list (use evals: [] for an empty manifest)")
    entries, seen = [], set()
    fields = {"config", "run", "parallelism", "max_turns", "setup_script", "triggers", "eval_cases_dir"}
    required = {"config", "run", "parallelism", "max_turns"}
    for index, entry in enumerate(document["evals"]):
        label = f"evals[{index}]"
        if not isinstance(entry, dict) or not required <= entry.keys() or entry.keys() - fields:
            raise EvalError(f"{label}: expected {sorted(required)}; optional: setup_script, triggers, eval_cases_dir")
        config = entry["config"]
        repo_file(repo, config, f"{label}.config")
        if PurePosixPath(config).suffix not in (".yaml", ".yml") or config in seen:
            raise EvalError(f"{label}.config must be a unique YAML config path")
        seen.add(config)
        if entry["run"] not in ("pr", "periodic", "manual"):
            raise EvalError(f"{label}.run must be pr, periodic, or manual")
        for field in ("parallelism", "max_turns"):
            if (not isinstance(entry[field], int) or isinstance(entry[field], bool)
                    or entry[field] <= 0):
                raise EvalError(f"{label}.{field} must be a positive integer")
        setup = entry.get("setup_script", "")
        if "setup_script" in entry:
            repo_file(repo, setup, f"{label}.setup_script")
        cases_dir = entry.get("eval_cases_dir", "")
        if "eval_cases_dir" in entry:
            repo_directory(repo, cases_dir, f"{label}.eval_cases_dir")
        triggers = entry.get("triggers", [])
        if not isinstance(triggers, list) or (entry["run"] == "pr" and not triggers):
            raise EvalError(f"{label}.triggers must be a list, nonempty for run: pr")
        for trigger in triggers:
            relative_path(trigger, f"{label}.triggers")
        entries.append(Eval(config, entry["run"], entry["parallelism"],
                            entry["max_turns"], setup, tuple(triggers), cases_dir))
    return entries


def matches_triggers(path, triggers):
    """Match literal paths and descendants, never partial path segments."""
    return any(path == trigger.rstrip("/") or path.startswith(trigger.rstrip("/") + "/")
               for trigger in triggers)


def select_evals(entries, files):
    selected = []
    for entry in entries:
        if entry.run != "pr":
            print(f"SKIP {entry.config}: run: {entry.run} is not executed in PR mode", flush=True)
            continue
        match = next((path for path in files if matches_triggers(path, entry.triggers)), None)
        if match is None:
            print(f"SKIP {entry.config}: no changed file matches triggers {entry.triggers}", flush=True)
        else:
            print(f"MATCH {entry.config}: {match!r}", flush=True)
            selected.append(entry)
    return selected


def select_cases(repo, entry, files, config_chain=()):
    """Return exact changed case IDs, or None to run the full dataset.

    This policy is deliberately separate from eval trigger matching: adding a
    case directory does not enroll new triggers. Prefer a full run whenever a
    relevant change cannot be attributed to a surviving case directory.
    """
    reason = "eval_cases_dir is not set"
    if entry.eval_cases_dir:
        prefix = entry.eval_cases_dir.rstrip("/") + "/"
        # Config/setup/manifest changes invalidate a subset even when omitted
        # from triggers. They do not independently select an otherwise skipped eval.
        controls = {MANIFEST, entry.config, entry.setup_script, *config_chain}
        relevant = [path for path in files if matches_triggers(path, entry.triggers)
                    or path.startswith(prefix) or path in controls]
        reason = "no attributable case changes"
        case_ids = set()
        for path in relevant:
            if path in controls or not path.startswith(prefix):
                reason = f"change outside individual cases: {path!r}"
                break
            case_id, separator, _ = path[len(prefix):].partition("/")
            case_path = (repo / entry.eval_cases_dir / case_id).resolve()
            if (not separator or case_id.startswith("-") or not case_path.is_dir()):
                reason = f"shared file, removed case, or ambiguous case path: {path!r}"
                break
            if not case_path.is_relative_to((repo / entry.eval_cases_dir).resolve()):
                raise EvalError(f"case directory escapes eval_cases_dir: {path!r}")
            case_ids.add(case_id)
        else:
            if case_ids:
                cases = tuple(sorted(case_ids))
                print(f"CASES {entry.config}: changed cases {cases!r}", flush=True)
                return cases
    print(f"CASES {entry.config}: full dataset ({reason})", flush=True)
    return None


def read_eval(repo, entry, harness, result_path, eval_artifacts, env, deadline):  # pylint: disable=too-many-arguments,too-many-positional-arguments
    """Resolve one config in a bounded child using the pinned harness loader."""
    time_left = deadline - time.monotonic()
    if time_left <= 0:
        raise EvalError("step time limit reached during config preflight")
    result_path.unlink(missing_ok=True)
    log = eval_artifacts / "config-resolution.log"
    helper = Path(__file__).with_name("eval_config.py")
    try:
        status = command([sys.executable, str(helper), "--harness", str(harness),
                          "--repo", str(repo), "--config", entry.config,
                          "--result", str(result_path)],
                         repo, env, log, min(CONFIG_RESOLUTION_TIMEOUT, time_left))
    except subprocess.TimeoutExpired as error:
        with log.open("ab") as output:
            output.write(f"config resolver timed out after {error.timeout} seconds\n".encode())
        raise EvalError(f"{entry.config}: config resolver timed out; see config-resolution.log") from error
    if status:
        raise EvalError(f"{entry.config}: configuration resolution failed (exit {status}); "
                        "see config-resolution.log")
    try:
        document = json.loads(result_path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as error:
        with log.open("ab") as output:
            output.write(f"invalid resolver result: {error}\n".encode())
        raise EvalError(f"{entry.config}: missing or malformed config resolver result: {error}; "
                        "see config-resolution.log") from error
    try:
        return validate_resolution_result(document, repo, entry.config, entry.eval_cases_dir)
    except EvalError as error:
        with log.open("ab") as output:
            output.write(f"parent validation failed: {error}\n".encode())
        raise


def command(args, repo, env, log, timeout, *, stdout=None, append=False, capture_output=False):  # pylint: disable=too-many-arguments
    """Run a bounded process group, optionally capturing its small stdout."""
    if capture_output and stdout is not None:
        raise ValueError("capture_output cannot be combined with a stdout target")
    log.parent.mkdir(parents=True, exist_ok=True)
    mode = "ab" if append else "wb"
    with log.open(mode) as output:
        target = subprocess.PIPE if capture_output else (stdout if stdout is not None else output)
        with subprocess.Popen(args, cwd=repo, env=env, stdin=subprocess.DEVNULL,
                              stdout=target, stderr=output, start_new_session=True,
                              text=capture_output) as process:
            try:
                if capture_output:
                    captured, _ = process.communicate(timeout=max(0.01, timeout))
                    return process.returncode, captured
                return process.wait(timeout=max(0.01, timeout))
            except BaseException:
                # Popen's timeout kills only the immediate child; downloads,
                # Python resolvers, and setup scripts can have descendants.
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                raise


def xml_text(text):
    """Render XML 1.0-illegal code points visibly without changing raw diagnostics."""
    return "".join(
        char if (ord(char) in (9, 10, 13) or 0x20 <= ord(char) <= 0xD7FF
                 or 0xE000 <= ord(char) <= 0xFFFD or 0x10000 <= ord(char) <= 0x10FFFF)
        else f"\\u{ord(char):04x}" for char in text)


def write_junit(artifacts, results):
    suite = ET.Element("testsuite", name="claude-eval", tests=str(len(results)),
                       failures=str(sum(bool(r[2]) for r in results)),
                       time=f"{sum(r[1] for r in results):.3f}")
    for name, duration, failure in results:
        case = ET.SubElement(suite, "testcase", name=xml_text(f"[sig-claude] {name} evaluation"),
                             time=f"{duration:.3f}")
        if failure:
            ET.SubElement(case, "failure", message=xml_text(failure)).text = xml_text(failure)
    destination = artifacts / "junit_claude-eval.xml"
    temporary = destination.with_suffix(".tmp")
    ET.ElementTree(suite).write(temporary, encoding="utf-8", xml_declaration=True)
    ET.parse(temporary)  # Publish only a report that XML consumers can read.
    temporary.replace(destination)


def run_directory(runs, run_id):
    # The harness owns the eval-name directory (it need not equal the filename).
    matches = [p for p in runs.glob(f"*/{run_id}") if p.is_dir()]
    if (runs / run_id).is_dir():  # Also support the older flat harness layout.
        matches.append(runs / run_id)
    # A harness invocation can expose the same run through an eval/skill alias.
    # Count physical directories, and archive their contents rather than a link.
    directories = {path.resolve() for path in matches}
    if any(not path.is_relative_to(runs.resolve()) for path in directories):
        raise EvalError(f"harness run directory for {run_id} escapes the runs directory")
    if len(directories) != 1:
        raise EvalError(f"expected exactly one harness run directory for {run_id}, found {len(directories)}")
    return directories.pop()


def collect_result(directory, artifacts):
    errors = []
    for filename, suffix in (("summary.yaml", "summary.yaml"),
                             ("report.html", "report-summary.html"),
                             ("run_result.json", "run_result.json")):
        source = directory / filename
        try:
            if source.is_file():
                (artifacts / suffix).write_bytes(source.read_bytes())
        except OSError as error:
            errors.append(f"cannot collect {filename}: {error}")
    if errors:
        raise EvalError("; ".join(errors))


def verify_result(directory, settings):
    thresholds = validate_thresholds(settings.get("thresholds", {}))
    try:
        result = json.loads((directory / "run_result.json").read_text(encoding="utf-8"))
        summary = yaml.safe_load((directory / "summary.yaml").read_text(encoding="utf-8"))
    except (OSError, ValueError, yaml.YAMLError) as error:
        raise EvalError(f"missing or invalid harness results: {error}") from error
    if (not isinstance(result, dict) or not isinstance(result.get("exit_code"), int)
            or isinstance(result["exit_code"], bool) or result["exit_code"] != 0):
        raise EvalError("harness execution failed or did not report an exit_code")
    if not isinstance(summary, dict) or not isinstance(summary.get("judges"), dict):
        raise EvalError("harness did not produce a judges summary")
    if not (directory / "report.html").is_file():
        raise EvalError("harness did not produce report.html")
    # score.py regression currently ignores a completely absent judge. Treat
    # missing thresholded judges as incomplete; let the harness interpret limits.
    for judge in thresholds:
        if judge not in summary["judges"]:
            raise EvalError(f"missing thresholded judge in summary: {judge}")


def archive(directory, artifacts):
    destination = artifacts / "eval-run.tar"
    temporary = destination.with_suffix(".tmp")
    try:
        # CI artifact processing removes the .gz suffix from compressed files.
        # Use a plain tar so the uploaded name still matches the static index.
        with tarfile.open(temporary, "w") as output:
            output.add(directory, arcname="run")
        temporary.replace(destination)
    finally:
        temporary.unlink(missing_ok=True)


def summary_data(artifacts, entries, errors):
    """Build the versioned, model-independent summary shared by agents and HTML."""
    counts = {status: sum(entry["status"] == status for entry in entries)
              for status in ("passed", "failed", "not run")}
    status = ("failed" if errors or counts["failed"] else
              "not_run" if counts["not run"] else "passed" if entries else "no_evals")
    evaluations = []
    filenames = ("report-summary.html", "summary.yaml", "run_result.json", "claude-eval.log",
                 "config-resolution.log", "setup.log", "regression.log", "metrics.log", "eval-run.tar")
    for entry in entries:
        directory = Path("evals") / entry["name"]
        files = {name: (directory / name).as_posix() for name in filenames
                 if (artifacts / directory / name).is_file()}
        evaluations.append({"config": entry["config"], "artifact_name": entry["name"],
                            "run_id": entry["run_id"] or None,
                            "status": entry["status"].replace(" ", "_"),
                            "failure": entry["failure"] or None,
                            "artifact_dir": directory.as_posix() + "/"
                            if (artifacts / directory).is_dir() else None,
                            "artifacts": files})
    install_log = "runner/harness-install.log"
    return {"schema_version": 1, "status": status,
            "counts": {"selected": len(entries), "passed": counts["passed"],
                       "failed": counts["failed"], "not_run": counts["not run"]},
            "errors": list(errors), "evals": evaluations,
            "artifacts": {"harness_install_log": install_log}
            if (artifacts / install_log).is_file() else {}}


def write_summary(artifacts, entries, errors):
    """Publish JSON atomically, including incomplete and failed evaluations."""
    destination = artifacts / "evals-summary.json"
    temporary = destination.with_suffix(".tmp")
    temporary.write_text(json.dumps(summary_data(artifacts, entries, errors),
                                    ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    temporary.replace(destination)


def write_index(artifacts, entries, errors):
    """Render the published JSON; retain HTML diagnostics if JSON writing failed."""
    try:
        summary = json.loads((artifacts / "evals-summary.json").read_text(encoding="utf-8"))
        if summary["errors"] != errors:
            summary = summary_data(artifacts, entries, errors)
    except (OSError, ValueError):
        summary = summary_data(artifacts, entries, errors)
    document = render_report(summary, link_json=(artifacts / "evals-summary.json").is_file())
    destination = artifacts / "evals-summary.html"
    temporary = destination.with_suffix(".tmp")
    temporary.write_text(document, encoding="utf-8")
    temporary.replace(destination)


def write_reports(artifacts, results, entries, errors):
    """Try every report even when one output cannot be written."""
    previous_errors = len(errors)
    for label, writer, args in (("JSON summary", write_summary, (artifacts, entries, errors)),
                                ("index", write_index, (artifacts, entries, errors)),
                                ("JUnit", write_junit, (artifacts, results))):
        try:
            writer(*args)
        except Exception as error:  # pylint: disable=broad-exception-caught
            message = f"cannot write {label}: {type(error).__name__}: {error}"
            if message not in errors:
                errors.append(message)
                results.append(("artifact reporting", 0, message))
            print(f"ERROR: {message}", flush=True)
    if len(errors) != previous_errors:
        # Refresh both indexes if a later report writer failed.
        for writer in (write_summary, write_index):
            try:
                writer(artifacts, entries, errors)
            except Exception:  # pylint: disable=broad-exception-caught
                pass  # The original reporting error is already recorded above.


def emit_metrics(env, repo, artifacts, eval_artifacts, *, stream_log, result, run_id, prompt,  # pylint: disable=too-many-arguments
                 timeout=60):
    # Keep accounting bounded and non-fatal, including for incomplete eval runs.
    try:
        if timeout <= 0:
            print(f"WARNING: metrics extraction skipped after the step deadline for {run_id}", flush=True)
            return
        status = command([sys.executable, str(Path(__file__).with_name("eval_metrics.py")),
                          "/opt/ai-helpers/plugins/prow-agent/scripts/extract_metrics.py",
                          str(stream_log), str(result) if result else "",
                          str(artifacts / "claude-session-metrics-autodl.json"),
                          env.get("BUILD_ID", "unknown"), run_id, prompt],
                         repo, env, eval_artifacts / "metrics.log", min(60, timeout))
        if status:
            print(f"WARNING: metrics extraction failed for {run_id}", flush=True)
    except Exception as error:  # pylint: disable=broad-exception-caught
        print(f"WARNING: metrics extraction failed: {error}", flush=True)


def remaining(deadline):
    """Return seconds left in the one step-wide monotonic deadline."""
    return deadline - time.monotonic()


def prepare_harness(repo, env, runner_artifacts, temporary, deadline):
    """Fetch and verify exactly the pinned harness revision."""
    harness = Path(temporary) / "plugin"
    install_log = runner_artifacts / "harness-install.log"
    install_log.write_text(f"Expected harness revision: {HARNESS_REVISION}\n", encoding="utf-8")
    steps = (
        (["git", "init", "--quiet", str(harness)], 60, "initialize the harness checkout"),
        (["git", "-C", str(harness), "remote", "add", "origin", HARNESS_URL],
         60, "configure the harness remote"),
        (["git", "-C", str(harness), "fetch", "--no-tags", "--depth", "1",
          "origin", HARNESS_REVISION], 300, "fetch the pinned harness revision"),
        (["git", "-C", str(harness), "checkout", "--quiet", "--detach", "FETCH_HEAD"],
         60, "check out the pinned harness revision"),
    )
    for args, timeout, action in steps:
        left = remaining(deadline)
        if left <= 0:
            raise EvalError("step time limit reached during harness preparation; see runner/harness-install.log")
        with install_log.open("ab") as output:
            output.write(("$ " + shlex.join(args) + "\n").encode())
        try:
            status = command(args, repo, env, install_log, min(timeout, left), append=True)
        except subprocess.TimeoutExpired as error:
            with install_log.open("ab") as output:
                output.write(f"ERROR: {action} timed out after {error.timeout} seconds\n".encode())
            raise EvalError(f"cannot {action}: step time limit reached; see runner/harness-install.log") from error
        except OSError as error:
            with install_log.open("ab") as output:
                output.write(f"{type(error).__name__}: {error}\n".encode())
            raise EvalError(f"cannot {action}; see runner/harness-install.log") from error
        if status:
            with install_log.open("ab") as output:
                output.write(f"ERROR: {action} exited with status {status}\n".encode())
            raise EvalError(f"cannot {action} (exit {status}); see runner/harness-install.log")

    left = remaining(deadline)
    if left <= 0:
        raise EvalError("step time limit reached while verifying the harness; see runner/harness-install.log")
    try:
        status, actual = command(["git", "-C", str(harness), "rev-parse", "HEAD"],
                                 repo, env, install_log, min(30, left),
                                 append=True, capture_output=True)
    except subprocess.TimeoutExpired as error:
        with install_log.open("ab") as output:
            output.write(f"ERROR: git rev-parse timed out after {error.timeout} seconds\n".encode())
        raise EvalError("step time limit reached while verifying the harness; see runner/harness-install.log") from error
    except OSError as error:
        with install_log.open("ab") as output:
            output.write(f"{type(error).__name__}: {error}\n".encode())
        raise EvalError("cannot verify harness revision; see runner/harness-install.log") from error
    actual = actual.strip()
    with install_log.open("ab") as output:
        output.write(f"Verified harness revision: {actual}\n".encode())
    if status:
        raise EvalError(f"cannot verify harness revision (exit {status}); see runner/harness-install.log")
    if actual != HARNESS_REVISION:
        message = f"harness revision mismatch: expected {HARNESS_REVISION}, got {actual!r}"
        with install_log.open("ab") as output:
            output.write(f"ERROR: {message}\n".encode())
        raise EvalError(f"{message}; see runner/harness-install.log")
    return harness


def preflight_evals(repo, entries, files, artifacts, harness, temporary, env,  # pylint: disable=too-many-arguments,too-many-positional-arguments
                    deadline, results, errors, index):
    """Resolve every selected config before allowing setup or model execution."""
    plans = []
    failed = False
    for entry, record in zip(entries, index):
        left = remaining(deadline)
        if left <= 0:
            message = f"{entry.config}: step time limit reached before config preflight completed"
            errors.append(message)
            results.append(("config preflight", 0, message))
            print(f"ERROR: {message}", flush=True)
            failed = True
            break
        started = time.monotonic()
        eval_artifacts = artifacts / "evals" / record["name"]
        result_path = Path(temporary) / f"{record['name']}.json"
        try:
            resolved = read_eval(repo, entry, harness, result_path, eval_artifacts, env, deadline)
            cases = select_cases(repo, entry, files, resolved["config_chain"]) or ()
            plans.append(EvalPlan(entry.config, resolved["settings"], resolved["model"],
                                  entry.parallelism, entry.max_turns, entry.setup_script,
                                  tuple(cases), resolved["config_chain"]))
        except Exception as error:  # pylint: disable=broad-exception-caught
            message = f"{entry.config}: {type(error).__name__}: {error}"
            record.update(status="failed", failure=message)
            errors.append(message)
            results.append((entry.config, time.monotonic() - started, message))
            print(f"ERROR: {message}", flush=True)
            failed = True
    return None if failed else plans


def run_evals(repo, entries, files, artifacts, env, *, deadline=None):  # pylint: disable=too-many-arguments,too-many-statements
    """Prepare, preflight, execute, and report selected manifest entries."""
    deadline = deadline if deadline is not None else time.monotonic() + STEP_TIMEOUT
    results, errors = [], []
    index = [{"config": entry.config, "name": artifact_name(entry.config),
              "run_id": "", "status": "not run", "failure": ""} for entry in entries]
    runs = Path(env.get("AGENT_EVAL_RUNS_DIR") or "eval/runs")
    if not runs.is_absolute():
        runs = repo / runs
    runs = runs.resolve()
    child_env = env.copy()
    child_env.pop("EVAL_SNAPSHOT_DIR", None)
    child_env["AGENT_EVAL_RUNS_DIR"] = str(runs)
    child_env["CLAUDE_CODE_ENTRYPOINT"] = "sdk-cli"
    started = time.monotonic()

    try:
        for record in index:
            (artifacts / "evals" / record["name"]).mkdir(parents=True, exist_ok=True)
        write_reports(artifacts, results, index, errors)
        runner_artifacts = artifacts / "runner"
        runner_artifacts.mkdir(exist_ok=True)
        token_path = Path(env.get("GITHUB_TOKEN_PATH") or "/nonexistent")
        if token_path.is_file():
            child_env["GITHUB_TOKEN"] = token_path.read_text(encoding="utf-8").strip()
        with tempfile.TemporaryDirectory(prefix="agent-eval-harness-") as temporary:
            harness = prepare_harness(repo, child_env, runner_artifacts, temporary, deadline)
            child_env["PYTHONPATH"] = os.pathsep.join(
                [str(harness), str(repo), child_env.get("PYTHONPATH", "")])
            plans = preflight_evals(repo, entries, files, artifacts, harness, temporary,
                                    child_env, deadline, results, errors, index)
            write_reports(artifacts, results, index, errors)
            if plans is None:
                return 1

            for plan, record in zip(plans, index):
                name = record["name"]
                run_id = f"ci-{name}-{uuid.uuid4().hex[:12]}"
                record["run_id"] = run_id
                eval_artifacts = artifacts / "evals" / name
                run_env = child_env.copy()
                run_env["ARTIFACT_DIR"] = str(eval_artifacts)
                begin = time.monotonic()
                failures = []
                execution_completed = False
                invoked = False
                directory = None
                stream_log = eval_artifacts / "claude-eval.log"
                args = ["--config", plan.config, "--model", plan.model,
                        "--run-id", run_id, "--parallelism", str(plan.parallelism)]
                if plan.cases:
                    args.extend(["--cases", *plan.cases])
                prompt = "/eval-run " + shlex.join(args)
                print(f"RUN {plan.config}: model={plan.model}, parallelism={plan.parallelism}, "
                      f"orchestrator max_turns={plan.max_turns}", flush=True)
                try:
                    if remaining(deadline) <= 0:
                        raise EvalError("step time limit reached before this eval could start")
                    if plan.setup_script:
                        setup_log = eval_artifacts / "setup.log"
                        with tempfile.TemporaryFile() as output:
                            status = command(["bash", plan.setup_script], repo, run_env, setup_log,
                                             remaining(deadline), stdout=output)
                            output.seek(0)
                            snapshot = output.read().decode().rstrip("\n")
                        if status:
                            raise EvalError(f"setup_script failed (exit {status}); see {setup_log.name}")
                        run_env["EVAL_SNAPSHOT_DIR"] = snapshot
                    if remaining(deadline) <= 0:
                        raise EvalError("step time limit reached during setup")
                    invoked = True
                    status = command(["claude", "--model", env.get("CLAUDE_MODEL", "claude-opus-4-6"),
                                      "--plugin-dir", str(harness), "--allowedTools",
                                      "Bash Read Write Edit Grep Glob Agent Skill",
                                      "--output-format", "stream-json", "--max-turns", str(plan.max_turns),
                                      "-p", prompt, "--verbose"], repo, run_env, stream_log,
                                     min(EVAL_TIMEOUT, remaining(deadline)))
                    if status:
                        raise EvalError(f"Claude orchestrator failed (exit {status}); see {stream_log.name}")
                    directory = run_directory(runs, run_id)
                    verify_result(directory, plan.settings)
                    # Score the verified physical run through the same harness
                    # checkout that resolved this original overlay config.
                    status = command([sys.executable, str(Path(__file__).with_name("eval_regression.py")),
                                      "--harness", str(harness), "--repo", str(repo),
                                      "--config", plan.config, "--run-dir", str(directory)],
                                     repo, run_env, eval_artifacts / "regression.log",
                                     min(60, remaining(deadline)))
                    if status:
                        raise EvalError("harness regression check failed; see regression log")
                    execution_completed = True
                except Exception as error:  # pylint: disable=broad-exception-caught
                    failures.append(f"{type(error).__name__}: {error}")
                except Interrupted as error:
                    failures.append(str(error))
                    raise
                finally:
                    finalized = False
                    try:
                        if invoked:
                            directory = None
                            try:
                                directory = run_directory(runs, run_id)
                            except Exception as error:  # pylint: disable=broad-exception-caught
                                failures.append(f"locate run: {type(error).__name__}: {error}")
                            if directory is not None:
                                for label, action in (("collect results", collect_result), ("archive run", archive)):
                                    try:
                                        action(directory, eval_artifacts)
                                    except Exception as error:  # pylint: disable=broad-exception-caught
                                        failures.append(f"{label}: {type(error).__name__}: {error}")
                            emit_metrics(env, repo, artifacts, eval_artifacts, stream_log=stream_log,
                                         result=directory / "run_result.json" if directory else None,
                                         run_id=run_id, prompt=prompt,
                                         timeout=remaining(deadline))
                        finalized = True
                    finally:
                        # Escaping control-flow exceptions must not become success.
                        if not (execution_completed and finalized) and not failures:
                            failures.append("eval did not complete")
                        failure = "; ".join(dict.fromkeys(failures))
                        record.update(status="failed" if failure else "passed", failure=failure)
                        results.append((plan.config, time.monotonic() - begin, failure))
                        write_reports(artifacts, results, index, errors)
                print(f"{'FAIL' if failure else 'PASS'} {plan.config}: {failure or 'complete'}", flush=True)
    except (Exception, Interrupted) as error:  # pylint: disable=broad-exception-caught
        message = f"{type(error).__name__}: {error}"
        errors.append(message)
        results.append(("eval runner", time.monotonic() - started, message))
        print(f"ERROR: {error}", flush=True)
    finally:
        write_reports(artifacts, results, index, errors)
    return int(any(result[2] for result in results))


def interrupted(signum, _frame):
    raise Interrupted(f"interrupted by signal {signum}")


def select_manifest_entries(repo, env):
    """Validate manifest and diff inputs, then select only explicit triggers."""
    if env.get("EVAL_DISCOVER") or env.get("EVAL_CONFIG", "eval.yaml") not in ("", "eval.yaml"):
        raise EvalError("the manifest workflow does not accept EVAL_DISCOVER or explicit EVAL_CONFIG")
    if env.get("EVAL_EXTRA_ARGS"):
        raise EvalError("EVAL_EXTRA_ARGS is not supported in manifest mode; settings belong in the manifest/eval YAML")
    if env.get("JOB_TYPE", "presubmit") != "presubmit":
        raise EvalError("manifest mode currently supports PR runs only (periodic/manual are follow-on work)")
    entries = load_manifest(repo)
    files = changed_files(repo, env.get("PULL_BASE_SHA", "")) if any(e.run == "pr" for e in entries) else []
    return select_evals(entries, files), files


def main():
    env = dict(os.environ)
    deadline = time.monotonic() + STEP_TIMEOUT
    repo = Path(env.get("EVAL_WORKDIR") or os.getcwd()).resolve()
    artifacts = Path(env["ARTIFACT_DIR"]).resolve()
    artifacts.mkdir(parents=True, exist_ok=True)
    env["ARTIFACT_DIR"] = str(artifacts)
    signal.signal(signal.SIGTERM, interrupted)
    signal.signal(signal.SIGINT, interrupted)
    try:
        selected, files = select_manifest_entries(repo, env)
        if not selected:
            print("No evaluations selected; exiting without setup, harness installation, or Claude calls.",
                  flush=True)
            results = []
            write_reports(artifacts, results, [], [])
            return int(bool(results))
    except (EvalError, Interrupted, OSError, ValueError) as error:
        print(f"ERROR: {error}", flush=True)
        write_reports(artifacts, [("eval selection", 0, str(error))], [], [str(error)])
        return 1
    return run_evals(repo, selected, files, artifacts, env, deadline=deadline)


if __name__ == "__main__":
    sys.exit(main())
PYTHON_SOURCE_2
cat > "${runner_dir}/eval_metrics.py" <<'PYTHON_SOURCE_3'
#!/usr/bin/env python3
"""AutoDL accounting ported from the legacy eval step, without a Bash bridge."""

import datetime
import importlib.util
import json
import pathlib
import sys
from collections import Counter

def main(args):  # pylint: disable=too-many-statements
    extractor_path, stream_path, result_path, output_path, build_id, run_id, prompt = args

    spec = importlib.util.spec_from_file_location("extract_metrics", extractor_path)
    metrics = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(metrics)
    analyzed_at = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    rows = []


    def empty_row():
        return {
            key: "" if field_type == "string" else "0"
            for key, field_type in metrics.SCHEMA.items()
        }


    def add_orchestrator_rows():  # pylint: disable=too-many-statements
        stream_file = pathlib.Path(stream_path)
        if not stream_file.is_file():
            return

        init = None
        result = None
        seen_tools = set()
        tool_counts = Counter()
        skills = []
        files_written = 0
        thinking_blocks = 0
        agent_tools = 0
        with stream_file.open(encoding="utf-8", errors="replace") as stream:
            for line in stream:
                try:
                    record = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if record.get("type") == "system" and record.get("subtype") == "init" and init is None:
                    init = record
                if record.get("type") == "result":
                    result = record
                if record.get("type") != "assistant":
                    continue
                content = record.get("message", {}).get("content", [])
                if not isinstance(content, list):
                    continue
                for block in content:
                    if not isinstance(block, dict):
                        continue
                    if block.get("type") == "thinking":
                        thinking_blocks += 1
                        continue
                    if block.get("type") != "tool_use":
                        continue
                    tool_id = str(block.get("id", ""))
                    if tool_id and tool_id in seen_tools:
                        continue
                    if tool_id:
                        seen_tools.add(tool_id)
                    tool_name = str(block.get("name", ""))
                    if not tool_name:
                        continue
                    tool_counts[tool_name] += 1
                    tool_input = block.get("input", {})
                    if not isinstance(tool_input, dict):
                        tool_input = {}
                    if tool_name == "Skill":
                        skill = str(tool_input.get("skill", ""))
                        if skill:
                            skills.append(skill)
                    elif tool_name == "Write":
                        files_written += 1
                    elif tool_name == "Agent":
                        agent_tools += 1

        if init is None or result is None:
            return
        model_usages = result.get("modelUsage", {})
        if not isinstance(model_usages, dict) or not model_usages:
            usage = result.get("usage", {})
            if not isinstance(usage, dict):
                usage = {}
            model_usages = {
                init.get("model", "unknown"): {
                    "inputTokens": usage.get("input_tokens", 0),
                    "outputTokens": usage.get("output_tokens", 0),
                    "cacheReadInputTokens": usage.get("cache_read_input_tokens", 0),
                    "cacheCreationInputTokens": usage.get("cache_creation_input_tokens", 0),
                    "costUSD": result.get("total_cost_usd", 0),
                }
            }
        total_cost = sum(float(usage.get("costUSD", 0) or 0) for usage in model_usages.values())
        primary_model = str(init.get("model", ""))
        plugins = ",".join(
            str(plugin.get("name", ""))
            for plugin in init.get("plugins", [])
            if isinstance(plugin, dict) and plugin.get("name")
        )
        for model, usage in model_usages.items():
            cost = float(usage.get("costUSD", 0) or 0)
            duration_ratio = cost / total_cost if total_cost else 1 / len(model_usages)
            input_tokens = int(usage.get("inputTokens", 0) or 0)
            output_tokens = int(usage.get("outputTokens", 0) or 0)
            cache_read = int(usage.get("cacheReadInputTokens", 0) or 0)
            cache_create = int(usage.get("cacheCreationInputTokens", 0) or 0)
            total_input = input_tokens + cache_read + cache_create
            cache_hit_rate = cache_read / total_input * 100 if total_input else 0
            is_primary = str(model) == primary_model
            session_id = str(result.get("session_id") or init.get("session_id", ""))
            if len(model_usages) > 1:
                session_id = f"{session_id}:{model}"
            row = empty_row()
            row.update({
                "session_id": session_id,
                "model": str(model),
                "claude_code_version": str(init.get("claude_code_version", "")),
                "permission_mode": str(init.get("permissionMode", "")),
                "entrypoint": "sdk-cli",
                "prompt": prompt[:500],
                "plugins_loaded": plugins,
                "analyzed_at": analyzed_at,
                "duration_ms": str(int(int(result.get("duration_ms", 0) or 0) * duration_ratio)),
                "duration_api_ms": str(int(int(result.get("duration_api_ms", 0) or 0) * duration_ratio)),
                "ttft_ms": str(int(result.get("ttft_ms", 0) or 0) if is_primary else 0),
                "num_turns": str(int(result.get("num_turns", 0) or 0) if is_primary else 0),
                "total_cost_usd": f"{cost:.6f}",
                "input_tokens": str(input_tokens),
                "output_tokens": str(output_tokens),
                "cache_read_input_tokens": str(cache_read),
                "cache_creation_input_tokens": str(cache_create),
                "cache_hit_rate_pct": f"{cache_hit_rate:.1f}",
                "total_tool_calls": str(sum(tool_counts.values()) if is_primary else 0),
                "tool_call_breakdown": json.dumps(dict(tool_counts.most_common())) if is_primary else "{}",
                "skills_invoked": ",".join(dict.fromkeys(skills)) if is_primary else "",
                "files_written": str(files_written if is_primary else 0),
                "num_thinking_blocks": str(thinking_blocks if is_primary else 0),
                "num_subagents": str(agent_tools if is_primary else 0),
                "is_error": "1" if result.get("is_error", False) else "0",
                "terminal_reason": str(result.get("terminal_reason", "")),
                "stop_reason": str(result.get("stop_reason", "")),
            })
            rows.append(row)


    def add_harness_rows():  # pylint: disable=too-many-statements
        result_file = pathlib.Path(result_path) if result_path else None
        if result_file is None or not result_file.is_file():
            return
        with result_file.open(encoding="utf-8") as stream:
            result = json.load(stream)
        usages = result.get("per_model_usage", {})
        if not isinstance(usages, dict) or not usages:
            model = result.get("model", "unknown")
            usage = result.get("token_usage", {})
            if not isinstance(usage, dict):
                usage = {}
            usages = {model: {**usage, "cost_usd": result.get("cost_usd", 0)}}
        model_turns = result.get("per_model_turns", {})
        if not isinstance(model_turns, dict):
            model_turns = {}
        # Missing/null is unavailable, not a measured zero. Keep known counts
        # even for models without token usage; never assign run totals per model.
        model_turns = {model: int(value) for model, value in model_turns.items() if value is not None}
        usages = {**{model: {} for model in model_turns}, **usages}
        missing_turns = sorted(set(usages) - model_turns.keys())
        if missing_turns:
            print(f"Per-model turns unavailable for {missing_turns}; "
                  "omit their counts and record any known unattributed total separately")
        total_turns = sum(model_turns.values())
        run_turns = result.get("num_turns")
        unattributed_turns = max(0, int(run_turns) - total_turns) if run_turns is not None else None
        total_cost = sum(float(usage.get("cost_usd", 0) or 0) for usage in usages.values())
        duration_s = float(result.get("duration_s", 0) or result.get("wall_clock_s", 0) or 0)
        if not duration_s:
            per_case = result.get("per_case", {})
            cases = per_case.values() if isinstance(per_case, dict) else per_case if isinstance(per_case, list) else []
            duration_s = sum(
                float(case.get("duration_s", 0) or 0)
                for case in cases
                if isinstance(case, dict)
            )
        duration_ms = max(1, int(duration_s * 1000))
        eval_params = result.get("eval_params", {})
        if not isinstance(eval_params, dict):
            eval_params = {}
        skill = str(eval_params.get("skill", ""))
        skill_args = str(eval_params.get("skill_args", ""))
        harness_prompt = f"/{skill} {skill_args}".strip() if skill else prompt

        for model, usage in usages.items():
            turns = model_turns.get(model)
            cost = float(usage.get("cost_usd", 0) or 0)
            input_tokens = int(usage.get("input", 0) or 0)
            output_tokens = int(usage.get("output", 0) or 0)
            cache_read = int(usage.get("cache_read", 0) or 0)
            cache_create = int(usage.get("cache_creation", 0) or 0)
            total_input = input_tokens + cache_read + cache_create
            if cost <= 0 and total_input <= 0 and output_tokens <= 0 and turns is None:
                continue
            if total_turns and not missing_turns and not unattributed_turns:
                duration_ratio = turns / total_turns
            elif total_cost:
                duration_ratio = cost / total_cost
            else:
                duration_ratio = 1 / len(usages)
            cache_hit_rate = cache_read / total_input * 100 if total_input else 0
            exit_code = int(result.get("exit_code", 0) or 0)
            row = empty_row()
            row.update({
                "session_id": f"eval-harness:{build_id}:{run_id}:{model}",
                "model": str(model),
                "claude_code_version": str(result.get("agent_version", "")).split(" ", 1)[0],
                "permission_mode": "default",
                "entrypoint": "agent-eval-harness",
                "prompt": harness_prompt[:500],
                "plugins_loaded": "agent-eval-harness",
                "analyzed_at": analyzed_at,
                "duration_ms": str(max(1, int(duration_ms * duration_ratio))),
                "total_cost_usd": f"{cost:.6f}",
                "input_tokens": str(input_tokens),
                "output_tokens": str(output_tokens),
                "cache_read_input_tokens": str(cache_read),
                "cache_creation_input_tokens": str(cache_create),
                "cache_hit_rate_pct": f"{cache_hit_rate:.1f}",
                "tool_call_breakdown": "{}",
                "skills_invoked": skill,
                "is_error": "1" if exit_code else "0",
                "terminal_reason": "eval_failed" if exit_code else "eval_complete",
                "stop_reason": "eval_failed" if exit_code else "end_turn",
            })
            # AutoDL columns are optional: absence means unknown, while "0"
            # is a measured zero. Never serialize None as "None" or a zero.
            if turns is None:
                row.pop("num_turns", None)
            else:
                row["num_turns"] = str(turns)
            rows.append(row)

        if unattributed_turns or (unattributed_turns == 0 and not model_turns):
            # An accounting-only row preserves the total without fabricating a
            # model attribution or duplicating token, cost, or duration metrics.
            row = empty_row()
            row.update({
                "session_id": f"eval-harness-unattributed:{build_id}:{run_id}",
                "model": "",
                "entrypoint": "agent-eval-harness",
                "prompt": harness_prompt[:500],
                "analyzed_at": analyzed_at,
                "num_turns": str(unattributed_turns),
                "is_error": "1" if result.get("exit_code") else "0",
                "terminal_reason": "unattributed_turns",
            })
            rows.append(row)


    add_orchestrator_rows()
    add_harness_rows()
    if not rows:
        sys.exit(1)

    output = pathlib.Path(output_path)
    if output.is_file():
        try:
            with output.open(encoding="utf-8") as stream:
                document = json.load(stream)
        except (json.JSONDecodeError, OSError) as error:
            raise RuntimeError(f"cannot read existing AutoDL artifact: {error}") from error
        if not isinstance(document, dict) or document.get("schema") != metrics.SCHEMA:
            raise RuntimeError("existing AutoDL artifact has an incompatible schema")
        existing_rows = document.setdefault("rows", [])
        if not isinstance(existing_rows, list):
            raise RuntimeError("existing AutoDL artifact rows must be a list")
        existing_rows.extend(rows)
    else:
        document = metrics.build_autodl(rows[0])
        document["rows"] = rows
    temporary = output.with_suffix(output.suffix + ".tmp")
    with temporary.open("w", encoding="utf-8") as stream:
        json.dump(document, stream, indent=4)
    temporary.replace(output)
    print(f"Wrote {len(rows)} eval metric row(s) to {output}")


if __name__ == "__main__":
    main(sys.argv[1:])
